<!doctype html>
<html lang='en'><head><meta name='viewport' content='width=device-width, initial-scale=1'><title>AgriConnect ERP</title>
<style>:root{--forest:#153d2b;--emerald:#26865c;--sage:#e7f0e8;--off:#f8faf7}*{box-sizing:border-box}html{overflow-x:hidden}body{width:100%;margin:0;min-width:0;overflow-x:hidden;font:16px/1.6 system-ui,sans-serif;color:#26352d;background:var(--off)}nav,section,footer{width:100%;max-width:100%;padding:25px 8%}nav{display:flex;justify-content:space-between;align-items:center;gap:24px;background:#fff}nav b{color:var(--forest);min-width:0}nav span{display:flex;justify-content:flex-end;gap:16px;flex-wrap:wrap;min-width:0}nav a{color:var(--forest);font-weight:700;text-decoration:none;white-space:nowrap}.hero{width:100%;min-height:520px;padding:92px 8%;display:flex;flex-direction:column;justify-content:center;align-items:stretch;overflow:hidden;background:linear-gradient(110deg,var(--forest),#237a52);color:#fff}.hero h1{width:100%;min-width:0;margin:0;max-width:800px;font-size:clamp(40px,6vw,72px);line-height:1.08;word-break:normal;overflow-wrap:anywhere}.hero p{width:100%;min-width:0;max-width:980px;overflow-wrap:anywhere}.actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:24px;max-width:100%}.btn{display:inline-flex;min-width:0;background:var(--emerald);color:#fff;padding:12px 16px;border-radius:8px;text-decoration:none;font-weight:700}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:16px}.card{background:#fff;padding:20px;border-radius:12px;min-height:68px;display:flex;align-items:center}.sage{background:var(--sage)}footer{background:var(--forest);color:#fff}@media(max-width:600px){nav{padding:20px 8%;align-items:flex-start;flex-wrap:wrap;gap:12px}nav b{flex:1 1 100%}nav span{width:100%;justify-content:flex-start;gap:10px}.hero{padding:72px 8%;min-height:560px}.hero h1{max-width:calc(100vw - 16%);font-size:clamp(34px,10vw,42px)}.hero p{max-width:calc(100vw - 16%)}.actions{display:grid;grid-template-columns:1fr;gap:10px;width:100%}.btn{width:100%;flex:none;justify-content:center}}</style></head>
<body><nav><b>AGRI CONNECT - Bongabong MAO</b><span><a href='/login'>Login</a><a href='/register'>Farmer Registration</a></span></nav>
<section class='hero'><h1>Empowering Agriculture Through Connected Digital Services</h1><p>AgriConnect connects farmer registration, agricultural monitoring, resource management, and municipal agriculture services in Bongabong.</p><div class='actions'><a class='btn' href='#services'>Explore Services</a><a class='btn' href='/register'>Farmer Registration</a><a class='btn' href='/login'>Login to Portal</a></div></section>
<section id='about'><h2>About AgriConnect</h2><p>Connected digital services for farmers and the Municipal Agriculture Office.</p></section>
<section id='services'><h2>Agricultural Services</h2><div class='grid'><div class='card'>Farmer and Farm Registration</div><div class='card'>Agricultural Production Monitoring</div><div class='card'>Inventory and Supply</div><div class='card'>Agricultural Assistance and Subsidies</div><div class='card'>Equipment and Asset Management</div><div class='card'>Budget and Procurement Management</div></div></section>
<section class='sage'><h2>How AgriConnect Works</h2><p>Register, receive MAO verification, then access agricultural services and assistance.</p></section>
<section><h2>Farmer Services</h2><p>Manage profiles, farms, applications, and distributions through the Farmer Portal.</p></section>
<footer>AgriConnect ERP - Bongabong Municipal Agriculture Office</footer></body></html>
